func02.starter_code:
# ==============================================================================
# Exercise: func02
# Chapter: 04_functions (Built-in Functions & Collections)
#
# Task:
# HCL provides powerful functions for manipulating collections (lists, maps):
# - merge(m1, m2, ...) combines multiple maps (later arguments override earlier)
# - lookup(map, key, default) retrieves a key or returns fallback if absent
# - distinct(list) removes duplicate elements while preserving order
# - slice(list, start, end) extracts a subset of a list
# - flatten(nested_list) recursively flattens nested lists into a single list
# - zipmap(keys, values) builds a map from paired lists of equal length
#
# Complete the locals block below:
# 1. merged_tags: merge var.default_tags with var.custom_tags
# 2. owner: lookup "Owner" in local.merged_tags, defaulting to "Platform"
# 3. unique_zones: remove duplicates from var.raw_zones with distinct()
# 4. primary_zones: slice the first 2 elements (index 0 to 2) from unique_zones
# 5. flat_subnets: flatten var.nested_subnets into a 1D list
# 6. config_map: zipmap var.keys_list and var.values_list
#
# ==============================================================================

terraform {
  required_version = ">= 1.6.0"
}

variable "default_tags" {
  type = map(string)
  default = {
    "Environment" = "dev"
    "ManagedBy"   = "terralings"
  }
}

variable "custom_tags" {
  type = map(string)
  default = {
    "Environment" = "prod"
    "CostCenter"  = "cc-100"
  }
}

variable "raw_zones" {
  type    = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1a", "us-east-1c", "us-east-1b"]
}

variable "nested_subnets" {
  type    = list(list(string))
  default = [["10.0.1.0/24", "10.0.2.0/24"], ["10.0.3.0/24"]]
}

variable "keys_list" {
  type    = list(string)
  default = ["db_host", "db_port"]
}

variable "values_list" {
  type    = list(string)
  default = ["10.0.0.5", "5432"]
}

locals {
  # TODO (What): Compute merged_tags = merge(var.default_tags, var.custom_tags).
  # TODO (Why): merge() overlays right-hand maps over left-hand maps, allowing callers to override defaults cleanly.
  merged_tags = {}

  # TODO (What): Compute owner = lookup(local.merged_tags, "Owner", "Platform").
  # TODO (Why): lookup() safely extracts a map entry or returns a specified fallback when the key is missing without raising an error.
  owner = ""

  # TODO (What): Compute unique_zones = distinct(var.raw_zones).
  # TODO (Why): distinct() eliminates redundant entries from input lists, ensuring idempotency when provisioning multi-zone resources.
  unique_zones = []

  # TODO (What): Compute primary_zones = slice(local.unique_zones, 0, 2).
  # TODO (Why): slice() selects a sub-range [start, end) from a list, allowing configuration to target a fixed subset of zones.
  primary_zones = []

  # TODO (What): Compute flat_subnets = flatten(var.nested_subnets).
  # TODO (Why): flatten() collapses nested list hierarchies into a single linear list suitable for resource count or for_each loops.
  flat_subnets = []

  # TODO (What): Compute config_map = zipmap(var.keys_list, var.values_list).
  # TODO (Why): zipmap() pairs parallel lists of keys and values into a single map object dynamically.
  config_map = {}
}

resource "terraform_data" "collections" {
  input = {
    tags    = local.merged_tags
    owner   = local.owner
    zones   = local.primary_zones
    subnets = local.flat_subnets
    config  = local.config_map
  }

  lifecycle {
    postcondition {
      condition     = length(local.primary_zones) == 2 && length(local.flat_subnets) == 3 && local.owner == "Platform" && lookup(local.config_map, "db_port", "") == "5432"
      error_message = "Collections must be transformed as expected (distinct/sliced zones, flattened subnets, merged tags, and zipmap config)."
    }
  }
}

