terraform {
  required_version = ">= 1.6.0"
  required_providers {
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "files" {
  type = map(string)
  default = {
    "index.html" = "<html><body>Hello Terralings</body></html>"
