# --- File: main.tf ---
# ==============================================================================
# Exercise: module03
# Chapter: 08_modules (Modular Infrastructure Architecture)
#
# Task:
# OpenTofu and Terraform support `for_each` and `count` on `module` blocks to
# instantiate multiple distinct instances of a child module.
#
# In this exercise:
# 1. Instantiate `./modules/worker` using `for_each` over `var.workers` map.
# 2. Pass `worker_name = each.key` and `concurrency = each.value` to each module.
# 3. Expose `output "worker_ids"` as a map of `{ worker_name => module.workers[worker_name].worker_id }`
#    using a `for` expression: `{ for k, w in module.workers : k => w.worker_id }`.
#
# ==============================================================================

variable "workers" {
  type = map(number)
  default = {
    "crawler"   = 4
    "indexer"   = 8
    "processor" = 2
  }
}

module "workers" {
  source = "./modules/worker"

  # TODO (What): Add for_each = var.workers, passing worker_name = each.key and concurrency = each.value.
  # TODO (Why): Using for_each on modules scales whole architectural sub-stacks with clean key-addressable module instances (module.workers["crawler"]).
  # for_each    = var.workers
  # worker_name = each.key
  # concurrency = each.value
}

output "worker_ids" {
  # TODO (What): Build map of worker_id outputs using value = { for k, w in module.workers : k => w.worker_id }.
  # TODO (Why): For comprehensions project keyed child module instance outputs into consolidated parent maps.
  # value = { for k, w in module.workers : k => w.worker_id }
  value = {}
}


# --- File: modules/worker/main.tf ---
resource "terraform_data" "worker" {
  input = {
    id          = "worker-${var.worker_name}"
    concurrency = var.concurrency
  }
}


# --- File: modules/worker/outputs.tf ---
output "worker_id" {
  description = "Worker identifier"
  value       = terraform_data.worker.output.id
}


# --- File: modules/worker/variables.tf ---
variable "worker_name" {
  type        = string
  description = "Unique worker identifier"
}

variable "concurrency" {
  type        = number
  description = "Concurrent job limit"
}

