# --- File: main.tf ---
# ==============================================================================
# Exercise: module04
# Chapter: 08_modules (Modular Infrastructure Architecture)
#
# Task:
# By default, child modules inherit default (un-aliased) provider configurations
# from the caller. When a child module needs an aliased provider (e.g. for a
# secondary region, account, or custom config), you must:
# 1. Declare `configuration_aliases = [local.target]` in the child module's
#    `terraform.required_providers.local` block.
# 2. Pass `providers = { local.target = local.backup }` in the parent module block.
#
# In this exercise:
# 1. Update `modules/storage/main.tf` to declare `configuration_aliases = [local.target]`.
# 2. In this root `main.tf`, pass `providers = { local.target = local.backup }` to `module.backup_storage`.
#
# ==============================================================================

terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
    }
  }
}

provider "local" {
  alias = "backup"
}

module "backup_storage" {
  source    = "./modules/storage"
  file_name = "backup.log"

  # TODO (What): Pass the aliased provider map: providers = { local.target = local.backup }.
  # TODO (Why): The providers map in module calls routes specific provider configurations to child module configuration aliases.
  # providers = {
  #   local.target = local.backup
  # }
}

output "backup_path" {
  value = module.backup_storage.path
}


# --- File: modules/storage/main.tf ---
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
      # TODO (What): Add configuration_aliases = [local.target].
      # TODO (Why): Declaring configuration_aliases informs the engine that this child module expects an explicit provider alias passed by parent modules.
    }
  }
}

resource "local_file" "log" {
  provider = local.target
  filename = "${path.module}/${var.file_name}"
  content  = "backup initialised\n"
}


# --- File: modules/storage/outputs.tf ---
output "path" {
  description = "Written file path"
  value       = local_file.log.filename
}


# --- File: modules/storage/variables.tf ---
variable "file_name" {
  type        = string
  description = "Target log file name"
}

